#!/usr/bin/env node
/**
 * Guards for the airdrop announcement (/news/omc-airdrop-is-open and its
 * Chinese mirror).
 *
 * The announcement is the page an answer engine is most likely to quote,
 * because it is dated, it has an author, and it states the numbers in a
 * table. That makes it the page where a stale figure does the most damage,
 * so the figures are asserted against contracts/params.json here rather than
 * trusted to a human re-reading it after every parameter change.
 *
 * Generated by website/tools/build_announcement.py — edit that, not the HTML.
 */

import assert from "node:assert/strict";
import { readFileSync, existsSync } from "node:fs";
import { test } from "node:test";

const ROOT = new URL("..", import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1");
const WEB = ROOT + "website";
const params = JSON.parse(readFileSync(ROOT + "contracts/params.json", "utf8"));
const a = params.airdrop;

const EN = WEB + "/news/omc-airdrop-is-open.html";
const ZH = WEB + "/zh/news/omc-airdrop-is-open.html";
const SLUG = "omc-airdrop-is-open";

const en = readFileSync(EN, "utf8");
const zh = readFileSync(ZH, "utf8");

function ldBlocks(html) {
  return [...html.matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g)]
    .map((m) => JSON.parse(m[1]));
}

const th = (n) => n.toLocaleString("en-US");

test("the announcement exists in both languages", () => {
  assert.ok(existsSync(EN), "English announcement is missing — run website/tools/build_announcement.py");
  assert.ok(existsSync(ZH), "Chinese mirror is missing — run website/tools/build_announcement.py");
});

test("both pages publish a parseable NewsArticle", () => {
  for (const [name, html, lang] of [["en", en, "en"], ["zh", zh, "zh-Hans"]]) {
    const blocks = ldBlocks(html);
    const art = blocks.find((b) => b["@type"] === "NewsArticle");
    assert.ok(art, `${name}: no NewsArticle block`);
    assert.equal(art.inLanguage, lang);
    assert.ok(art.headline && art.headline.length > 20, `${name}: headline too short`);
    assert.ok(art.datePublished && !Number.isNaN(Date.parse(art.datePublished)), `${name}: bad datePublished`);
    assert.ok(art.dateModified && !Number.isNaN(Date.parse(art.dateModified)), `${name}: bad dateModified`);
    assert.equal(art.author["@type"], "Organization");
    assert.ok(art.publisher.logo.url.endsWith(".png"), `${name}: publisher logo missing`);
    assert.equal(art.isAccessibleForFree, true);
    assert.ok(blocks.some((b) => b["@type"] === "BreadcrumbList"), `${name}: no breadcrumb`);
  }
});

test("the announcement quotes the live parameters, not last month's", () => {
  for (const [name, html] of [["en", en], ["zh", zh]]) {
    assert.ok(html.includes(th(a.pool)), `${name}: pool ${a.pool} not stated`);
    assert.ok(html.includes(th(a.poolSlots)), `${name}: slot count ${a.poolSlots} not stated`);
    assert.ok(html.includes(String(a.perEntry)), `${name}: per-entry amount not stated`);
    assert.ok(html.includes(String(a.claimCost.feeBnb)), `${name}: claim fee not stated`);
    assert.ok(html.includes(a.claimOpens), `${name}: claim open date not stated`);
    assert.ok(html.includes(a.claimCloses), `${name}: claim close date not stated`);
  }
});

test("the announcement states the entry caps that params defines", () => {
  const cap = (a.baseEntries + a.referralEntries) * a.perEntry;
  for (const [name, html] of [["en", en], ["zh", zh]]) {
    assert.ok(html.includes(String(a.baseEntries)), `${name}: base entry cap not stated`);
    assert.ok(html.includes(String(a.referralEntries)), `${name}: referral cap not stated`);
    assert.ok(html.includes(String(cap)), `${name}: per-wallet cap ${cap} OMC not stated`);
  }
});

test("the announcement leads with free and does not call itself paid", () => {
  const enLower = en.toLowerCase();
  assert.ok(enLower.includes("free to join") || enLower.includes("free"), "en: free is not stated");
  assert.ok(zh.includes("免费"), "zh: 免费 is not stated");
  for (const banned of ["entrance fee", "paid airdrop", "cost to enter", "buy the airdrop"]) {
    assert.ok(!enLower.includes(banned), `en: must not describe itself as a paid airdrop ("${banned}")`);
  }
  // The fee has to be disclosed in the same page, not only on /airdrop.
  assert.ok(enLower.includes("processing fee"), "en: the claim fee is not named as a processing fee");
});

test("the announcement does not promise a shipped token", () => {
  const enLower = en.toLowerCase();
  assert.ok(enLower.includes("no mainnet"), "en: the pre-launch state must be stated");
  assert.ok(enLower.includes("no token contract") || enLower.includes("token contract"), "en: token contract status not stated");
});

test("hreflang points both ways between the two pages", () => {
  const urlEn = `https://omc.network/news/${SLUG}`;
  const urlZh = `https://omc.network/zh/news/${SLUG}`;
  for (const [name, html, self, other] of [["en", en, urlEn, urlZh], ["zh", zh, urlZh, urlEn]]) {
    assert.ok(html.includes(`<link rel="canonical" href="${self}">`), `${name}: canonical is not self-referential`);
    assert.ok(html.includes(`hreflang="en" href="${urlEn}"`), `${name}: missing en alternate`);
    assert.ok(html.includes(`hreflang="zh" href="${urlZh}"`), `${name}: missing zh alternate`);
  }
});

test("the sitemap lists both URLs", () => {
  const sm = readFileSync(WEB + "/sitemap.xml", "utf8");
  assert.ok(sm.includes(`https://omc.network/news/${SLUG}`), "sitemap is missing the English announcement");
  assert.ok(sm.includes(`https://omc.network/zh/news/${SLUG}`), "sitemap is missing the Chinese mirror");
});

test("the news feed links to the announcement and the pinned fallback renders without JS", () => {
  const data = readFileSync(WEB + "/assets/data/news.js", "utf8");
  assert.ok(data.includes(`/news/${SLUG}`), "assets/data/news.js has no entry for the announcement");
  const news = readFileSync(WEB + "/news.html", "utf8");
  assert.ok(news.includes(`/news/${SLUG}`), "news.html has no no-JS link to the announcement");
  // The list is rendered client-side; without a static fallback a crawler sees
  // an empty feed, which defeats the point of publishing an announcement.
  assert.ok(/<div class="news-list" id="newsList">\s*<!--/.test(news),
    "news.html must keep a static pinned item inside #newsList");
});

test("the Chinese mirror is actually Chinese", () => {
  const text = zh.replace(/<script[\s\S]*?<\/script>/g, "").replace(/<[^>]+>/g, " ");
  const zhChars = (text.match(/[\u4e00-\u9fff]/g) || []).length;
  assert.ok(zhChars > 600, `zh mirror has only ${zhChars} Chinese characters`);
  const leftovers = text.match(/[A-Za-z][A-Za-z' ]{30,}/g) || [];
  assert.deepEqual(leftovers, [], `zh mirror has untranslated English: ${leftovers.slice(0, 3)}`);
});

test("the copy-paste versions for external platforms quote the same numbers", () => {
  const docs = {
    en: readFileSync(ROOT + "docs/marketing/airdrop-announcement-en.md", "utf8"),
    zh: readFileSync(ROOT + "docs/marketing/airdrop-announcement-zh.md", "utf8"),
  };
  for (const [name, md] of Object.entries(docs)) {
    assert.ok(md.includes(th(a.pool)), `${name}: pool ${a.pool} not stated`);
    assert.ok(md.includes(th(a.poolSlots)), `${name}: slot count not stated`);
    assert.ok(md.includes(`20 OMC`), `${name}: per-entry amount not stated`);
    assert.ok(md.includes(`${a.claimCost.feeBnb} BNB`), `${name}: claim fee not stated`);
    assert.ok(md.includes("2027") && md.includes("2026"), `${name}: dates missing`);
    assert.ok(md.includes("omc.network/airdrop"), `${name}: no claim link`);
    // Same rule as the feed: never frame the fee as a price of entry.
    for (const banned of ["entrance fee", "paid airdrop", "cost to enter"]) {
      assert.ok(!md.toLowerCase().includes(banned), `${name}: "${banned}" must not appear`);
    }
  }
});
